from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = [c for c, n in Counter(v for row in grid for v in row).items() if c != 0 and n]
    if not colors:
        return [row[:] for row in grid]
    boxes = {}
    for c in colors:
        cells = [(r, j) for r in range(h) for j in range(w) if grid[r][j] == c]
        boxes[c] = (min(r for r, j in cells), max(r for r, j in cells), min(j for r, j in cells), max(j for r, j in cells))
    # The enclosing color forms the larger rectangle; the smaller color is the seed to extend.
    outer, inner = sorted(colors, key=lambda c: (-(boxes[c][1]-boxes[c][0]+1)*(boxes[c][3]-boxes[c][2]+1), c))[:2]
    ro0, ro1, co0, co1 = boxes[outer]
    ri0, ri1, ci0, ci1 = boxes[inner]
    # Grow the enclosing rectangle outward by the short side of the inner patch,
    # up to two cells (a singleton patch grows by one).
    pad = min(2, ri1-ri0+1, ci1-ci0+1)
    out = [row[:] for row in grid]
    for r in range(max(0, ro0-pad), min(h-1, ro1+pad)+1):
        for c in range(max(0, co0-pad), min(w-1, co1+pad)+1):
            if out[r][c] == 0:
                out[r][c] = inner
    return out

